'use strict';
/* Proposed aggregation of existing per-conversation keyPointsMarkdown.
   Fictional, in-memory fixtures only. Personal memory and conversation recall stay separate. */
window.workspaceModule = (() => {
  const records = [
    {id:'design',title:'Nola 的设计，先让内容被看见',updated:'刚刚',version:1,keyPointsMarkdown:'黑与白是默认底色，主题色只用于有意义的强调。\n\n手机对话列表优先呈现标题、最近上下文和必要的参与者信息，不照搬桌面侧栏。\n\n阅读行宽上限 720 px；手机按宽度使用 16 / 20 px 页边距。',wiki:'## 设计约定\n\n同一种身份与状态语义，适配不同平台的布局。\n\n正文与操作区分层，操作在需要时出现。',summary:'此前讨论了手机列表、主题色与排版。当前希望将同一套设计语言延伸到 Nola 各个页面。',history:['主题色不应铺满界面，白色和黑色是默认背景。','手机列表需要像真正的手机产品，而不是缩小的桌面侧栏。']},
    {id:'compare',title:'选模型前，先固定比较方法',updated:'昨天 16:20',version:1,keyPointsMarkdown:'用同一组任务比较首字延迟、生成速度与峰值内存。\n\n速度、资源和稳定性应分别记录，不用一个总分掩盖取舍。',wiki:'## 比较记录模板\n\n任务 → 输入 → 延迟 → 内存 → 完成质量。\n\n记录失败情况与恢复方式。',summary:'对话比较本地模型的评估维度，研究专家已完成，写作专家的一次回复中断。',history:['从速度、内存和日常体验三个角度比较。','日常体验还包括长对话稳定性和工具恢复。']},
    {id:'weekend',title:'周末的空白，也值得留下',updated:'今天 12:40',version:1,keyPointsMarkdown:'这次出行不追求密集行程；留一段能随时折返的路，也留一点什么都不做的时间。',wiki:'',summary:'想去山里或有水的地方，尚未选择目的地。只是聊天，没有创建计划。',history:['不想把行程排得太满。','上午慢慢出发，下午留一点空白。']}
  ];
  const memories = [
    {id:'m1',category:'偏好',text:'喜欢轻松、有留白的旅行安排。',confidence:'较高',evidence:[{id:'weekend',text:'周末，去山里走走',detail:'“不想把行程排得太满。”'},{id:'reading',text:'读到一句很喜欢的话',detail:'“不需要马上得到答案。”'}],updated:'今天'},
    {id:'m2',category:'工作',text:'重视界面的排版节奏和跨平台一致性。',confidence:'较高',evidence:[{id:'design',text:'让 Nola 更像 Nola',detail:'讨论默认背景、间距与移动端设计。'},{id:'long',text:'跨平台界面',detail:'统一信息与行为，同时尊重平台布局。'}],updated:'今天'},
    {id:'m3',category:'兴趣',text:'可能偏爱雨天的轻音乐。',confidence:'待确认',evidence:[{id:'music',text:'适合雨天的歌',detail:'一次歌单讨论；不足以视为固定偏好。'}],updated:'昨天'}
  ];
  let filter='全部', workspaceQuery='', memoryFilter='全部', contextId='design', tab='知识点', editor=null, recallQuery='';
  const sourceTitle = id => conversations.find(c=>c.id===id)?.title || '已不可用的来源会话';
  const paragraphs = text => `<div class="prose">${esc(text).split('\n\n').map(p=>`<p>${p.replace(/\n/g,'<br>')}</p>`).join('')}</div>`;
  const actions = s => `<div class="dialog-actions" style="flex-wrap:wrap">${s}</div>`;
  const button=(a,t,c='text-action')=>`<button class="${c}" data-action="${a}">${t}</button>`;
  function record(id){let r=records.find(x=>x.id===id);if(!r){r={id,title:sourceTitle(id),updated:'尚未整理',version:1,keyPointsMarkdown:'',wiki:'',summary:'尚无压缩摘要。',history:[]};records.push(r)}return r}
  function workspaceView(){const mobileKnowledge=window.architectureModule?.getMode()==='mobile'&&page==='knowledge';const found=records.filter(r=>r.keyPointsMarkdown&&(filter!=='今天'||r.updated==='刚刚'||r.updated.startsWith('今天'))&&(`${r.title} ${r.keyPointsMarkdown} ${sourceTitle(r.id)}`).includes(workspaceQuery));return `<section class="page">${mobileKnowledge?crumbs('会话知识点'):mobileBrand()}<header class="page-head"><div>${mobileKnowledge?'':'<div class="eyebrow">YOUR WORKSPACE</div>'}<h1>${mobileKnowledge?'会话知识点':'工作区'}</h1><p>值得留下的，已经为你整理在这里。</p></div>${mobileKnowledge?'':button('nav:manage','管理 '+svg('chevron'))}</header><div class="section-heading" style="margin-top:32px"><h2>对话里的关键要点</h2>${button('ws-about','整理说明')}</div><div class="tabs" role="group" aria-label="要点范围">${['全部','今天'].map(t=>button('ws-filter:'+t,t,t===filter?'selected':'')).join('')}</div><label class="search">${svg('search')}<input id="ws-search" aria-label="搜索关键要点" placeholder="找一个留下的想法" value="${esc(workspaceQuery)}"></label><div id="ws-point-list">${pointRows(found)}</div><div class="section-heading"><h2>关于你的长期记忆</h2>${button('nav:memory','查看 '+svg('chevron'))}</div><p class="muted" style="font-size:14px">与会话知识点分开保存。每条记忆都有依据，也可以修正或删除。</p><div class="demo-banner">演示内容 · 这里是既有会话知识点的聚合展示提案，不代表产品已有跨会话自动总结。</div></section>`}
  function pointRows(found){if(!found.length)return `<div class="empty-state"><h2>这里暂时没有要点</h2><p>换一个关键词或范围；也可以到对话的知识点里整理内容。</p>${button('ws-clear','显示全部')}</div>`;return found.map(r=>`<article style="padding:24px 0;border-bottom:1px solid var(--line)"><div style="display:flex;align-items:baseline;gap:12px;margin-bottom:12px"><h2 style="flex:1;font-size:19px;line-height:28px">${esc(r.title)}</h2><span class="meta" style="white-space:nowrap">${esc(r.updated)}</span></div>${paragraphs(r.keyPointsMarkdown)}<div style="display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:4px;margin-top:16px"><button class="text-action" style="color:var(--muted);font-size:12px;padding-left:0;white-space:normal;text-align:left" data-action="chat:${r.id}">${svg('chat')} ${esc(sourceTitle(r.id))}</button>${button('ws-detail:'+r.id,'查看与整理 '+svg('chevron'))}</div></article>`).join('')}
  function memoryView(){let list=memories.filter(m=>memoryFilter==='全部'||m.category===memoryFilter);return `<section class="page">${crumbs('长期记忆')}${pageHead('长期记忆','关于你的偏好与习惯，每一条都应有依据。')}<div class="tabs" role="group" aria-label="记忆类别">${['全部','偏好','工作','兴趣'].map(t=>button('ws-memory-filter:'+t,t,memoryFilter===t?'selected':'')).join('')}</div><div class="objects">${list.length?list.map(m=>`<button class="object-row" data-action="ws-memory:${m.id}"><div class="object-copy"><h3>${esc(m.text)}</h3><p>${esc(m.category)} · ${m.evidence.length} 条依据 · 置信度${esc(m.confidence)}</p><p class="meta">${esc(m.updated)}更新</p></div>${svg('chevron','chevron')}</button>`).join(''):`<div class="empty-state"><h2>这个类别还没有记忆</h2><p>不会因为一次闲聊就替你下结论。</p></div>`}</div><div class="demo-banner">虚构记忆示例 · 长期记忆不等于会话知识点，也不等于历史压缩摘要。</div></section>`}
  function context(id,t='知识点'){contextId=id;tab=t;const r=record(id);let body=`<p class="muted" style="font-size:13px;margin-bottom:20px">${esc(sourceTitle(id))}</p><div class="tabs" role="group" aria-label="会话上下文">${['知识点','Wiki','回忆'].map(t=>button('ws-tab:'+t,t,t===tab?'selected':'')).join('')}</div>`;
    if(tab==='回忆'){body+=`<div class="detail-section" style="margin-top:0"><h3>压缩摘要</h3><p>${esc(r.summary)}</p><p class="meta">这是会话上下文的压缩，不是长期记忆。</p></div><div class="detail-section"><h3>历史召回</h3><label for="ws-recall-search">在这段会话中查找</label><input id="ws-recall-search" placeholder="输入一个关键词" value="${esc(recallQuery)}"><div id="ws-recall-results">${recallResults(r)}</div></div>`}
    else {const content=tab==='Wiki'?r.wiki:r.keyPointsMarkdown;body+=`<p class="meta" style="margin-bottom:16px">${tab==='Wiki'?'独立 Wiki 文档 · 手动维护结构化内容':'源会话知识点 · 可编辑，工作区展示同步引用这里'}</p>${content?paragraphs(content):'<div class="empty-state"><h2>还没有内容</h2><p>留给值得整理的想法，不必每段闲聊都填满。</p></div>'}${actions(button('ws-edit:'+id+':'+(tab==='Wiki'?'wiki':'keyPointsMarkdown'),'编辑'+tab,'primary'))}`}
    body+=actions(button('chat:'+id,'回到来源对话'));openDialog('会话上下文',body);const search=dialog.querySelector('#ws-recall-search');if(search)search.oninput=()=>{recallQuery=search.value;dialog.querySelector('#ws-recall-results').innerHTML=recallResults(r);bind(dialog.querySelector('#ws-recall-results'))};}
  function recallResults(r){const matches=r.history.filter(s=>s.includes(recallQuery));return matches.length?matches.map(s=>`<div class="inline-block"><p>${esc(s)}</p>${button('chat:'+r.id,'打开来源会话')}</div>`).join(''):'<p class="dialog-note">没有匹配的历史片段。</p>'}
  function edit(id,field){const r=record(id);editor={id,field,base:r.version,draft:r[field],conflict:false};renderEditor()}
  function renderEditor(){const e=editor,r=record(e.id);openDialog(e.field==='wiki'?'编辑 Wiki':'编辑源知识点',`<form id="ws-edit-form"><label for="ws-edit-content">内容（纯文本 / Markdown）</label><textarea id="ws-edit-content" rows="8">${esc(e.draft)}</textarea>${e.conflict?`<div class="inline-block" role="alert"><h3>源内容有了新版本</h3><p>你的草稿仍在输入框里，没有覆盖新内容。请先查看最新版本，再决定保存。</p>${button('ws-latest','查看最新版本')}</div>`:''}<p class="dialog-note">保存只更新本地演示源；工作区同步显示知识点。当前源版本 ${r.version}。</p>${actions(button('ws-simulate-conflict','模拟另一处更新')+button('ws-cancel-edit','取消')+'<button class="primary" type="submit">保存</button>')}</form>`);dialog.querySelector('#ws-edit-content').oninput=ev=>editor.draft=ev.target.value;dialog.querySelector('#ws-edit-form').onsubmit=ev=>{ev.preventDefault();e.draft=dialog.querySelector('#ws-edit-content').value;if(r.version!==e.base){e.conflict=true;renderEditor();return}r[e.field]=e.draft;r.version++;r.updated='刚刚';editor=null;render();context(r.id,e.field==='wiki'?'Wiki':'知识点');toast('源内容已保存，工作区已同步（演示）')}}
  function memoryDetail(id){const m=memories.find(m=>m.id===id);if(!m)return;openDialog('这条记忆的依据',`${paragraphs(m.text)}<dl><div><dt>类别</dt><dd>${esc(m.category)}</dd></div><div><dt>置信度</dt><dd>${esc(m.confidence)} · 演示标注</dd></div></dl><h3>来自这些对话</h3>${m.evidence.map(e=>`<button class="choice-row" data-action="chat:${e.id}"><div><h3>${esc(e.text)}</h3><p>${esc(e.detail)}</p></div>${svg('chevron')}</button>`).join('')}${actions(button('ws-memory-delete:'+id,'删除记忆')+button('ws-memory-edit:'+id,'修正内容','primary'))}`)}
  function handle(action){if(!action.startsWith('ws-'))return false;const [a,id,field]=action.split(':');
    if(a==='ws-filter'){filter=id;render()}
    else if(a==='ws-clear'){filter='全部';workspaceQuery='';render()}
    else if(a==='ws-about')openDialog('如何整理这些要点',`<div class="prose"><p>首屏引用每段对话里已有的知识点，保留来源和更新时间。聚合展示是这次原型的设计提案，不是自动生成的每日综合结论。</p><p>在详情中编辑的是源会话知识点。Wiki、历史压缩摘要与长期记忆各自独立，不会混成同一种内容。</p><p>所有内容均为虚构演示，修改不会写入真实账户。</p></div>`);
    else if(a==='ws-detail'||a==='ws-context'){recallQuery='';context(id)}
    else if(a==='ws-tab')context(contextId,id);
    else if(a==='ws-edit')edit(id,field);
    else if(a==='ws-cancel-edit'){let e=editor;editor=null;context(e.id,e.field==='wiki'?'Wiki':'知识点')}
    else if(a==='ws-simulate-conflict'){editor.draft=dialog.querySelector('#ws-edit-content').value;const r=record(editor.id);r.version++;r[editor.field]+='\n\n另一处新增的演示备注：请保留来源上下文。';toast('已模拟源版本更新；保存将检测冲突')}
    else if(a==='ws-latest'){editor.draft=dialog.querySelector('#ws-edit-content').value;const r=record(editor.id);openDialog('对照最新版本',`<h3>最新源内容 · 版本 ${r.version}</h3>${paragraphs(r[editor.field])}<div class="detail-section"><h3>你的未保存草稿</h3>${paragraphs(editor.draft)}</div><p class="dialog-note">选择保留草稿后，可自行合并，再明确保存；不会自动覆盖。</p>${actions(button('ws-reload-source','加载最新内容')+button('ws-keep-draft','保留草稿并继续编辑','primary'))}`)}
    else if(a==='ws-reload-source'||a==='ws-keep-draft'){const r=record(editor.id);if(a==='ws-reload-source')editor.draft=r[editor.field];editor.base=r.version;editor.conflict=false;renderEditor()}
    else if(a==='ws-memory-filter'){memoryFilter=id;render()}
    else if(a==='ws-memory')memoryDetail(id);
    else if(a==='ws-memory-edit'){let m=memories.find(x=>x.id===id);openDialog('修正记忆',`<form id="ws-memory-form"><label for="ws-memory-text">记忆内容</label><textarea id="ws-memory-text" required>${esc(m.text)}</textarea><p class="dialog-note">保留原始依据；内容会标记为你手动修正。</p>${actions('<button class="primary" type="submit">保存修正</button>')}</form>`);dialog.querySelector('#ws-memory-form').onsubmit=e=>{e.preventDefault();let t=dialog.querySelector('textarea').value.trim();if(!t)return;m.text=t;m.confidence='已手动修正';m.updated='刚刚';render();memoryDetail(id)}}
    else if(a==='ws-memory-delete')openDialog('删除这条演示记忆？',`<p class="muted">只删除本地记忆项，不会删除来源对话。</p>${actions(button('ws-memory:'+id,'保留')+button('ws-memory-confirm-delete:'+id,'删除','primary'))}`);
    else if(a==='ws-memory-confirm-delete'){let i=memories.findIndex(x=>x.id===id);if(i>=0)memories.splice(i,1);closeDialog();render();toast('演示记忆已删除，来源对话保留')}
    return true;
  }
  function afterRender(){const search=document.querySelector('#ws-search');if(search)search.oninput=()=>{workspaceQuery=search.value;const found=records.filter(r=>r.keyPointsMarkdown&&(filter!=='今天'||r.updated==='刚刚'||r.updated.startsWith('今天'))&&(`${r.title} ${r.keyPointsMarkdown} ${sourceTitle(r.id)}`).includes(workspaceQuery));const list=document.querySelector('#ws-point-list');list.innerHTML=pointRows(found);bind(list)}}
  return {view:p=>p==='workspace'?workspaceView():p==='memory'?memoryView():null,handle,afterRender,records,memories};
})();
